#!/bin/bash
set -euo pipefail
cd "$(dirname "$0")/.."
mkdir -p .task-build
cmake -S . -B .task-build/lib -DCMAKE_BUILD_TYPE=Release -DCMAKE_POLICY_VERSION_MINIMUM=3.5 -DALSOFT_EMBED_HRTF_DATA=OFF -DALSOFT_RTKIT=OFF -DALSOFT_BACKEND_SDL2=OFF -DLIBTYPE=STATIC -DALSOFT_UTILS=OFF -DALSOFT_EXAMPLES=OFF -DALSOFT_INSTALL=OFF -DALSOFT_UPDATE_BUILD_VERSION=OFF -DALSOFT_OSX_FRAMEWORK=OFF -DALSOFT_BACKEND_PIPEWIRE=OFF -DALSOFT_BACKEND_PULSEAUDIO=OFF -DALSOFT_BACKEND_ALSA=OFF -DALSOFT_BACKEND_OSS=OFF -DALSOFT_BACKEND_SOLARIS=OFF -DALSOFT_BACKEND_SNDIO=OFF -DALSOFT_BACKEND_JACK=OFF -DALSOFT_BACKEND_COREAUDIO=OFF -DALSOFT_BACKEND_PORTAUDIO=OFF -DALSOFT_BACKEND_WAVE=OFF -DALSOFT_BACKEND_WINMM=OFF -DALSOFT_BACKEND_WASAPI=OFF -DALSOFT_BACKEND_DSOUND=OFF -DALSOFT_BACKEND_OPENSL=OFF -DALSOFT_BACKEND_OBOE=OFF -DALSOFT_CPUEXT_NEON=OFF
cmake --build .task-build/lib --parallel 4
